def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    full_colors = {row[0] for row in grid if all(v == row[0] for v in row) and row[0] != bg}
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        c = 0
        while c < w and row[c] != bg:
            c += 1
        if c == 0 or c == w:
            continue
        color = row[0]
        if color in full_colors and all(v == bg for v in row[c:]):
            for j in range(c, w):
                out[r][j] = 1
    return out
